import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cmath>
#define THREADS 512
#define BR 64
#define TPR 8
#define DK 128
#define DV 64
#define PADK 4
#define PADP 8
// CTA-tiled SDPA: one block handles BR query rows of one (batch, head).
// K/V tiles are staged in shared memory; TPR threads cooperate per row.
template <int NJ>
__global__ void __launch_bounds__(THREADS) sdpa_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    int B, int H, int S, int D,
    float scale
) {
    const int bh = blockIdx.x;
    const int row0 = blockIdx.y * BR;
    const size_t base = (size_t)bh * (size_t)S * (size_t)D;
    const __half* q = Q + base;
    const __half* k = K + base;
    const __half* v = V + base;
    __half* o = O + base;
    extern __shared__ __half smem[];
    __half* sQ = smem;
    __half* sK = sQ + BR * (DK + PADK);
    __half* sP = smem;
    __half* sV = smem + BR * (S + PADP);
    const int tid = threadIdx.x;
    const int r = tid / TPR;
    const int lane = tid % TPR;
    const int Dh2 = D >> 1;
    const int KSTR = DK + PADK;
    float sacc[NJ];
    #pragma unroll
    for (int u = 0; u < NJ; ++u) sacc[u] = 0.0f;
    // Phase A: scores = Q * K^T, tiled over the head dimension.
    for (int d0 = 0; d0 < D; d0 += DK) {
        {
            const int W = DK >> 1;
            const int total = BR * W;
            const __half2* qg = reinterpret_cast<const __half2*>(q) + (size_t)row0 * (size_t)Dh2 + (d0 >> 1);
            for (int idx = tid; idx < total; idx += THREADS) {
                const int rr = idx / W;
                const int cc = idx - rr * W;
                reinterpret_cast<__half2*>(sQ)[rr * (KSTR >> 1) + cc] = qg[(size_t)rr * (size_t)Dh2 + cc];
            }
        }
        {
            const int W = DK >> 1;
            const int total = S * W;
            const __half2* kg = reinterpret_cast<const __half2*>(k) + (d0 >> 1);
            for (int idx = tid; idx < total; idx += THREADS) {
                const int rr = idx / W;
                const int cc = idx - rr * W;
                reinterpret_cast<__half2*>(sK)[rr * (KSTR >> 1) + cc] = kg[(size_t)rr * (size_t)Dh2 + cc];
            }
        }
        __syncthreads();
        const __half2* q2 = reinterpret_cast<const __half2*>(sQ + r * KSTR);
        #pragma unroll 4
        for (int jj = 0; jj < NJ; ++jj) {
            const __half2* k2 = reinterpret_cast<const __half2*>(sK + (jj * TPR + lane) * KSTR);
            float dot = 0.0f;
            #pragma unroll 8
            for (int d2 = 0; d2 < (DK >> 1); ++d2) {
                const float2 qf = __half22float2(q2[d2]);
                const float2 kf = __half22float2(k2[d2]);
                dot = fmaf(qf.x, kf.x, dot);
                dot = fmaf(qf.y, kf.y, dot);
            }
            sacc[jj] += dot;
        }
        __syncthreads();
    }
    // Softmax: TPR lanes cooperate on one query row.
    float mx = -INFINITY;
    #pragma unroll
    for (int jj = 0; jj < NJ; ++jj) mx = fmaxf(mx, sacc[jj]);
    #pragma unroll
    for (int off = 1; off < TPR; off <<= 1)
        mx = fmaxf(mx, __shfl_xor_sync(0xffffffffu, mx, off));
    float sum = 0.0f;
    #pragma unroll
    for (int jj = 0; jj < NJ; ++jj) {
        const float e = expf((sacc[jj] - mx) * scale);
        sacc[jj] = e;
        sum += e;
    }
    #pragma unroll
    for (int off = 1; off < TPR; off <<= 1)
        sum += __shfl_xor_sync(0xffffffffu, sum, off);
    const float inv_sum = 1.0f / sum;
    const int PSTR = S + PADP;
    #pragma unroll
    for (int jj = 0; jj < NJ; ++jj)
        sP[r * PSTR + jj * TPR + lane] = __float2half_rn(sacc[jj] * inv_sum);
    __syncthreads();
    // Phase B: O = P * V, tiled over the head dimension.
    const int NC = DV / TPR;
    const int c0 = lane * NC;
    for (int d0 = 0; d0 < D; d0 += DV) {
        {
            const int W = DV >> 1;
            const int total = S * W;
            const __half2* vg = reinterpret_cast<const __half2*>(v) + (d0 >> 1);
            for (int idx = tid; idx < total; idx += THREADS) {
                const int rr = idx / W;
                const int cc = idx - rr * W;
                reinterpret_cast<__half2*>(sV)[rr * W + cc] = vg[(size_t)rr * (size_t)Dh2 + cc];
            }
        }
        __syncthreads();
        float acc[NC];
        #pragma unroll
        for (int u = 0; u < NC; ++u) acc[u] = 0.0f;
        const __half* pr = sP + r * PSTR;
        #pragma unroll 4
        for (int j = 0; j < S; ++j) {
            const float p = __half2float(pr[j]);
            const __half2* v2 = reinterpret_cast<const __half2*>(sV + j * DV + c0);
            #pragma unroll
            for (int u = 0; u < (NC >> 1); ++u) {
                const float2 vf = __half22float2(v2[u]);
                acc[2*u]   = fmaf(p, vf.x, acc[2*u]);
                acc[2*u+1] = fmaf(p, vf.y, acc[2*u+1]);
            }
        }
        __half2* o2 = reinterpret_cast<__half2*>(o + (size_t)(row0 + r) * (size_t)D + d0 + c0);
        #pragma unroll
        for (int u = 0; u < (NC >> 1); ++u)
            o2[u] = __floats2half2_rn(acc[2*u], acc[2*u+1]);
        __syncthreads();
    }
}
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
                "Q, K, V must be float16");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(),
                "Q, K, V must be contiguous");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q, K, V must have the same shape");
    const int B = (int)Q.size(0);
    const int H = (int)Q.size(1);
    const int S = (int)Q.size(2);
    const int D = (int)Q.size(3);
    TORCH_CHECK((S % BR) == 0 && S <= 256, "sequence_length must be a multiple of 64 and <= 256");
    TORCH_CHECK((D % DK) == 0, "embedding_dimension must be a multiple of 128");
    auto O = torch::empty_like(Q);
    const float scale = 1.0f / std::sqrt((float)D);
    const size_t smemA = ((size_t)BR + (size_t)S) * (size_t)(DK + PADK) * sizeof(__half);
    const size_t smemB = ((size_t)BR * (size_t)(S + PADP) + (size_t)S * (size_t)DV) * sizeof(__half);
    const size_t shmem_bytes = smemA > smemB ? smemA : smemB;
    static bool configured = false;
    if (!configured) {
        cudaFuncSetAttribute((const void*)sdpa_kernel<8>,  cudaFuncAttributeMaxDynamicSharedMemorySize, 96 * 1024);
        cudaFuncSetAttribute((const void*)sdpa_kernel<16>, cudaFuncAttributeMaxDynamicSharedMemorySize, 96 * 1024);
        cudaFuncSetAttribute((const void*)sdpa_kernel<24>, cudaFuncAttributeMaxDynamicSharedMemorySize, 96 * 1024);
        cudaFuncSetAttribute((const void*)sdpa_kernel<32>, cudaFuncAttributeMaxDynamicSharedMemorySize, 96 * 1024);
        configured = true;
    }
    const dim3 grid(B * H, S / BR);
    auto stream = at::cuda::getCurrentCUDAStream();
    const __half* qp = reinterpret_cast<const __half*>(Q.data_ptr<at::Half>());
    const __half* kp = reinterpret_cast<const __half*>(K.data_ptr<at::Half>());
    const __half* vp = reinterpret_cast<const __half*>(V.data_ptr<at::Half>());
    __half* op = reinterpret_cast<__half*>(O.data_ptr<at::Half>());
    switch (S / TPR) {
        case 8:  sdpa_kernel<8> <<<grid, THREADS, shmem_bytes, stream>>>(qp, kp, vp, op, B, H, S, D, scale); break;
        case 16: sdpa_kernel<16><<<grid, THREADS, shmem_bytes, stream>>>(qp, kp, vp, op, B, H, S, D, scale); break;
        case 24: sdpa_kernel<24><<<grid, THREADS, shmem_bytes, stream>>>(qp, kp, vp, op, B, H, S, D, scale); break;
        case 32: sdpa_kernel<32><<<grid, THREADS, shmem_bytes, stream>>>(qp, kp, vp, op, B, H, S, D, scale); break;
        default: TORCH_CHECK(false, "unsupported sequence_length");
    }
    return O;
}
'''
cpp_src = "torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);"
_mod = load_inline(
    name="custom_sdpa_single_kernel",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["sdpa_forward"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)
