    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    int B, int H, int S, int D,
    float scale
) {
    const int bh = blockIdx.x;
    const int i = threadIdx.x;

    const size_t qkv_base = (size_t)bh * (size_t)S * (size_t)D;
    const __half* q = Q + qkv_base;
    const __half* k = K + qkv_base;
    const __half* v = V + qkv_base;
    __half* o = O + qkv_base;

    float srow[MAX_S];
    __half prow[MAX_S];

    const int D2 = D >> 1;

    if (i < S) {
        const __half2* q2 = reinterpret_cast<const __half2*>(q + (size_t)i * (size_t)D);

        for (int j = 0; j < S; ++j) {
            const __half2* k2 = reinterpret_cast<const __half2*>(k + (size_t)j * (size_t)D);
            float dot = 0.0f;

            #pragma unroll 4
            for (int d2 = 0; d2 < D2; ++d2) {
                float2 qf = __half22float2(q2[d2]);
                float2 kf = __half22float2(k2[d2]);
                dot = fmaf(qf.x, kf.x, dot);
                dot = fmaf(qf.y, kf.y, dot);
            }

            srow[j] = dot * scale;
        }

        float mx = -INFINITY;
        for (int j = 0; j < S; ++j) {
            mx = fmaxf(mx, srow[j]);
        }

        float sum = 0.0f;
        for (int j = 0; j < S; ++j) {
            float e = expf(srow[j] - mx);
            sum += e;
            prow[j] = __float2half_rn(e);
        }

        float inv_sum = 1.0f / sum;
        for (int j = 0; j < S; ++j) {
            prow[j] = __float2half_rn(__half2float(prow[j]) * inv_sum);
        }
    }

    extern __shared__ __half shV[];

    for (int d0 = 0; d0 < D; d0 += DT) {
        const int total = S * DT;
        for (int idx = threadIdx.x; idx < total; idx += blockDim.x) {
            int r = idx / DT;
            int c = idx - r * DT;
            shV[idx] = v[(size_t)r * (size_t)D + (size_t)d0 + (size_t)c];
        }
        __syncthreads();

        if (i < S) {
            __half* orow = o + (size_t)i * (size_t)D + (size_t)d0;

            #pragma unroll 4
            for (int c = 0; c < DT; ++c) {
                float acc = 0.0f;
                for (int j = 0; j < S; ++j) {
                    float p = __half2float(prow[j]);
                    float vv = __half2float(shV[j * DT + c]);
                    acc = fmaf(p, vv, acc);
                }
                orow[c] = __float2half_rn(acc);
            }
        }
        __syncthreads();
    }
}

